/* What a move costs is derived from how strong it is, not hand-assigned:
   thirty moves would drift out of step with their numbers the first time
   anything was rebalanced. Damage and knockback both count, because a move
   that barely hurts but throws you off the stage still wins the game.

   Everything here is plain arithmetic on constants, so both machines in an
   online match compute identical costs. */
function moveCost(m) {
  if (!m) return 0;
  const shots = m.count || 1;
  let power = (m.damage || 0) * shots;

  // Damage over time is still damage; count all of it.
  if (m.poison) power += m.poison.frames * m.poison.dps;
  if (m.quake) power += m.quake.damage * 2;   // it lands twice, one each way

  // A buff does no damage itself, so price it by how much it multiplies
  // everything else, and for how long.
  if (m.kind === 'buff') {
    power += (m.duration / 60) * ((m.damageMul || 1) - 1) * 9;
  }

  // Knockback decides whether a hit takes a stock, so it is worth as much
  // as the damage attached to it.
  power += (m.base || 0) * 1.6 + (m.scale || 0) * 0.7;

  return Math.max(6, Math.round(3 + power * 1.15));
}

// Priced once at load. Jabs and ults stay free (see COMBAT.manaMax).
for (const key in ROSTER) {
  const def = ROSTER[key];
  for (const slot in def.specials) {
    def.specials[slot].mana = moveCost(def.specials[slot]);
  }
}

const ORDER = ['autisnick', 'johnnyham', 'kel', 'ladeane', 'reese', 'trev'];

/* =====================================================================
   CANVAS
   The world renders to a 320x180 buffer that gets integer-scaled with
   nearest-neighbor sampling, so the pixels stay exact squares. UI text
   is drawn afterwards at full device resolution so it stays readable.
   ===================================================================== */

// `data-nerdwars` marks an embedded mount: on a page the game doesn't own,
// it must not swallow the keyboard until the player clicks into it.
const mount = document.querySelector('[data-nerdwars]');
// data-nerdwars="online" hides local play entirely: the only way into a match
// is the lobby on the host page.
const onlineOnly = !!mount && mount.dataset.nerdwars === 'online';
const view = document.getElementById('nw-canvas') || document.getElementById('game');
const embedded = !!mount;
let hasFocus = !embedded;
const sctx = view.getContext('2d');
const world = document.createElement('canvas');
world.width = VW;
world.height = VH;
const ctx = world.getContext('2d');
ctx.imageSmoothingEnabled = false;

let SCALE = 4;

function resize() {
  // Measure the host element rather than the window, so the game fits
  // whatever box it's placed in -- the whole screen standalone, or a panel
  // when it's embedded in a page.
  const host = view.parentElement;
  // 320x180 divides exactly into every 16:9 resolution (720p is 4x, 1080p is
  // 6x, 1440p is 8x, 4K is 12x), so fullscreen lands on a whole scale with no
  // bars at all -- but only if nothing is subtracted first. (1920-16)/320
  // rounds down to 5, throwing away an entire step at the one size that fits
  // perfectly. Breathing room is the container's job, not the scale maths'.
  // In fullscreen, measure the window rather than the host element. The host
  // is the screen at that point, but its border and padding are subtracted
  // from clientWidth -- and a single pixel of border is enough to turn
  // 1920/320 = 6 into floor(1918/320) = 5, losing a whole scale step to CSS.
  // The window's inner size has no such trim.
  const fs = !!document.fullscreenElement;
  const pad = fs ? 0 : 8;
  const availW = fs ? window.innerWidth : ((host && host.clientWidth) || window.innerWidth);
  const availH = fs ? window.innerHeight : ((host && host.clientHeight) || window.innerHeight);
  const sx = Math.floor((availW - pad) / VW);
  const sy = Math.floor((availH - pad) / VH);
  SCALE = Math.max(1, Math.min(sx, sy));
  view.width = VW * SCALE;
  view.height = VH * SCALE;
  sctx.imageSmoothingEnabled = false;
}
function fullscreenHost() {
  return mount || view.parentElement || document.documentElement;
}

function fullscreenActive() {
  return !!document.fullscreenElement;
}

function toggleFullscreen() {
  if (fullscreenActive()) {
    if (document.exitFullscreen) document.exitFullscreen();
    return;
  }
  const el = fullscreenHost();
  if (el && el.requestFullscreen) el.requestFullscreen().catch(() => {});
}

document.addEventListener('fullscreenchange', () => {
  // Someone who just went fullscreen wants to play, not to click again.
  if (fullscreenActive()) {
    hasFocus = true;
    if (mount) mount.dataset.nerdwarsFocus = 'on';
  }
  resize();
});

// Wire any control marked as the fullscreen button, in any build.
document.addEventListener('click', (e) => {
  const btn = e.target.closest && e.target.closest('[data-nerdwars-fullscreen]');
  if (btn) {
    e.preventDefault();
    toggleFullscreen();
  }
});

window.addEventListener('resize', resize);
if (typeof ResizeObserver !== 'undefined' && view.parentElement) {
  new ResizeObserver(resize).observe(view.parentElement);
}
resize();

// Virtual -> device pixels, for drawing UI on top of the scaled world.
const S = (n) => n * SCALE;

/* =====================================================================
   ASSETS
   ===================================================================== */

const IMG = {};
let assetsReady = false;

function loadAssets(done) {
  const jobs = [];

  function grab(key, uri) {
    const im = new Image();
    const p = new Promise((res) => {
      im.onload = res;
      im.onerror = res;
    });
    im.src = uri;
    IMG[key] = im;
    jobs.push(p);
  }

  for (const name of ORDER) {
    const entry = SPRITES[name];
    for (const set of ['base', 'attack', 'shirtless']) {
      if (!entry[set]) continue;
      for (const frame in entry[set]) {
        grab(name + '.' + set + '.' + frame, entry[set][frame]);
      }
    }
  }
  SPRITES.bone.forEach((uri, i) => grab('bone.' + i, uri));
  for (const d in SPRITES.pizza) grab('pizza.' + d, SPRITES.pizza[d]);

  for (const theme in TILES) {
    for (const role in TILES[theme]) grab('tile.' + theme + '.' + role, TILES[theme][role]);
  }
  for (const k in UI) grab('ui.' + k, UI[k].src);

  Promise.all(jobs).then(() => { assetsReady = true; done(); });
}

/* =====================================================================
   INPUT
   ===================================================================== */

const held = new Set();
let prevHeld = new Set();

/* Each special has its own key. It used to be one SPECIAL button whose
   meaning depended on whether you were holding up or down, which meant you
   could not throw your down special without also fastfalling, or your up
   special without the game reading it as a jump input.

   Both hands, split by job. The left hand only moves and blocks -- WASD, and
   shift under the little finger. The right hand does all the attacking, on
   the home row it is already sitting on: H J K for the three specials, L for
   the ult, and G within reach of the left index for the free jab.

   The specials were on Q/F/C, which put them on the same hand as the
   movement keys. That is fine right up until you need to move and attack at
   the same time, which is most of a fight. */
const BINDS = [
  { left: 'KeyA', right: 'KeyD', up: 'KeyW', down: 'KeyS',
    // Space jumps too. It is the button every platformer has trained people
    // to reach for, and W is easy to miss while your hand is on A or D.
    jump2: 'Space',
    attack: 'KeyG', shield: 'ShiftLeft', ult: 'KeyL',
    spNeutral: 'KeyH', spDown: 'KeyJ', spUp: 'KeyK' },
  { left: 'ArrowLeft', right: 'ArrowRight', up: 'ArrowUp', down: 'ArrowDown',
    // Comma, not L: L is player 1's ult now.
    attack: 'Comma', shield: 'ShiftRight', ult: 'Quote',
    spNeutral: 'Period', spDown: 'Slash', spUp: 'Semicolon',
    // Numpad alternates, for keyboards where the punctuation cluster is awkward.
    attack2: 'Numpad0', shield2: 'Numpad4', ult2: 'Numpad5',
    spNeutral2: 'Numpad1', spDown2: 'Numpad2', spUp2: 'Numpad3' },
];

window.addEventListener('keydown', (e) => {
  // Before the focus check on purpose: this is a user gesture whatever the
  // game does with the key, and it is the only chance to start the context.
  audioUnlock();
  if (!hasFocus) return;
  // Stop the browser scrolling the page out from under the game.
  if (e.code.startsWith('Arrow') || e.code === 'Space' || e.code.startsWith('Numpad')) {
    e.preventDefault();
  }
  held.add(e.code);
});
window.addEventListener('keyup', (e) => held.delete(e.code));
window.addEventListener('blur', () => { held.clear(); });

if (embedded) {
  // Claim the keyboard on click inside the game, release it on click outside,
  // so the rest of the page keeps working normally.
  document.addEventListener('mousedown', (e) => {
    const inside = mount.contains(e.target);
    if (inside !== hasFocus) {
      hasFocus = inside;
      held.clear();
      mount.dataset.nerdwarsFocus = inside ? 'on' : 'off';
    }
  });
  mount.dataset.nerdwarsFocus = 'off';
}

function down(code) { return held.has(code); }
function tapped(code) { return held.has(code) && !prevHeld.has(code); }

// Reads one player's control scheme into a neutral shape the Fighter and
// the AI both understand -- which is what lets a CPU drive a Fighter
// through the exact same code path a human does.
/* =====================================================================
   GAMEPADS

   Two keyboard schemes is the keyboard's honest ceiling, so seats three and
   four are pads. Standard mapping throughout: face buttons 0-3, shoulders
   4-7, d-pad 12-15, left stick on axes 0 and 1.

   Polled, not evented, so the state is snapshotted once a frame and the
   previous snapshot is what makes an edge-triggered press detectable -- the
   same shape as `held` and `prevHeld` for keys, and rolled forward at the
   same guarded moment.
   ===================================================================== */

const GP_AXIS = 0.45;          // stick deflection that counts as a direction
let gpNow = [];
let gpPrev = [];

/** Snapshot every connected pad. Cheap, and called once a frame. */
function pollGamepads() {
  if (typeof navigator === 'undefined' || !navigator.getGamepads) {
    gpNow = [];
    return;
  }
  const list = navigator.getGamepads();
  const out = [];
  for (let i = 0; i < list.length && out.length < MAX_PLAYERS; i++) {
    const g = list[i];
    if (!g || !g.connected) continue;
    const b = [];
    for (let k = 0; k < g.buttons.length; k++) b.push(!!g.buttons[k].pressed);
    out.push({ b: b, ax: g.axes[0] || 0, ay: g.axes[1] || 0 });
  }
  gpNow = out;
}

function gamepadCount() {
  return gpNow.length;
}

/* The one place the game's actions are mapped onto a pad. Returns whether the
   action is held now, and (via `was`) whether it was held last frame. */
function gpState(g, action) {
  if (!g) return false;
  const b = g.b;
  const on = (i) => !!b[i];
  switch (action) {
    case 'left':  return on(14) || g.ax < -GP_AXIS;
    case 'right': return on(15) || g.ax > GP_AXIS;
    case 'up':    return on(12) || g.ay < -GP_AXIS;
    case 'down':  return on(13) || g.ay > GP_AXIS;
    case 'jump':  return on(0)  || on(12) || g.ay < -GP_AXIS;
    case 'attack':   return on(2);
    case 'shield':   return on(4) || on(5);
    case 'ult':      return on(3);
    case 'spNeutral': return on(1);
    case 'spDown':    return on(6);
    case 'spUp':      return on(7);
  }
  return false;
}

function gpDown(i, action) {
  return gpState(gpNow[i], action);
}

function gpTapped(i, action) {
  return gpState(gpNow[i], action) && !gpState(gpPrev[i], action);
}

/** A pad in the same shape readPad() produces, so nothing downstream cares. */
function readGamepad(i) {
  const spN = gpTapped(i, 'spNeutral');
  const spD = gpTapped(i, 'spDown');
  const spU = gpTapped(i, 'spUp');
  return {
    left: gpDown(i, 'left'),
    right: gpDown(i, 'right'),
    up: gpDown(i, 'up'),
    down: gpDown(i, 'down'),
    jump: gpTapped(i, 'jump'),
    attack: gpTapped(i, 'attack'),
    spNeutral: spN,
    spDown: spD,
    spUp: spU,
    special: spN || spD || spU,
    shield: gpDown(i, 'shield'),
    ult: gpTapped(i, 'ult'),
  };
}

/* Which controller drives seat `i`: the two keyboard schemes first, then pads
   in the order they were plugged in. */
function schemeFor(i) {
  return i < BINDS.length ? i : 'pad' + (i - BINDS.length);
}

/** One seat's input, whatever it happens to be plugged into. */
function readPadFor(f) {
  if (f.scheme === null || f.scheme === undefined) return Object.assign({}, NEUTRAL);
  if (typeof f.scheme === 'number') return readPad(f.scheme);
  return readGamepad(Number(f.scheme.slice(3)));
}

/* How many people could actually play right now: two on the keyboard plus a
   pad each for the rest. Used to decide how many of a four-way are humans. */
function humansAvailable() {
  return Math.min(MAX_PLAYERS, BINDS.length + gamepadCount());
}

function readPad(idx) {
  const b = BINDS[idx];
  const any = (a, c) => down(a) || (c && down(c));
  const anyTap = (a, c) => tapped(a) || (c && tapped(c));
  // Three separate buttons, plus `special` as "any of them", which is the
  // gate the Fighter and the AI both test before spending mana.
  const spN = anyTap(b.spNeutral, b.spNeutral2);
  const spD = anyTap(b.spDown, b.spDown2);
  const spU = anyTap(b.spUp, b.spUp2);
  return {
    left: down(b.left),
    right: down(b.right),
    up: down(b.up),
    down: down(b.down),
    jump: anyTap(b.up, b.jump2),
    attack: anyTap(b.attack, b.attack2),
    spNeutral: spN,
    spDown: spD,
    spUp: spU,
    special: spN || spD || spU,
    shield: any(b.shield, b.shield2),
    ult: anyTap(b.ult, b.ult2),
  };
}

const NEUTRAL = {
  left: false, right: false, up: false, down: false,
  jump: false, attack: false, special: false,
  spNeutral: false, spDown: false, spUp: false,
  shield: false, ult: false,
};

/* The 2016 menu art (BACK / QUIT) is 325x128 -- wider than the whole 320px
   playfield -- so it is drawn on the UI layer at device resolution instead of
   being crushed down into the world buffer. Each drawn button registers a hit
   rect so it works with the mouse as well as the key shown beside it. */
const uiButtons = [];

/* Where the pointer is, in device pixels. Menus only -- nothing here is read
   by the simulation, so hover can never differ between two machines mid-match
   and can never desync online play. -1 means the pointer is off the canvas. */
let mouseX = -1;
let mouseY = -1;

function viewPoint(e) {
  const r = view.getBoundingClientRect();
  return [(e.clientX - r.left) * (view.width / r.width),
          (e.clientY - r.top) * (view.height / r.height)];
}

function buttonAt(mx, my) {
  for (const b of uiButtons) {
    if (mx >= b.x && mx <= b.x + b.w && my >= b.y && my <= b.y + b.h) return b;
  }
  return null;
}

view.addEventListener('mousedown', (e) => {
  audioUnlock();
  const p = viewPoint(e);
  const b = buttonAt(p[0], p[1]);
  if (b) b.action();
});

view.addEventListener('mousemove', (e) => {
  const p = viewPoint(e);
  mouseX = p[0];
  mouseY = p[1];
  // The hit rects are from the frame just drawn. They only move when the
  // scene changes, so testing against last frame's is never wrong in practice.
  view.style.cursor = buttonAt(mouseX, mouseY) ? 'pointer' : '';
});

view.addEventListener('mouseleave', () => {
  mouseX = -1;
  mouseY = -1;
  view.style.cursor = '';
});

function drawButton(key, cxVirtual, cyVirtual, widthVirtual, action) {
  const meta = UI[key];
  const base = IMG['ui.' + key];
  if (!meta || !base) return;
  const w = px(widthVirtual);
  const h = w * (meta.h / meta.w);
  const x = px(cxVirtual) - w / 2;
  const y = px(cyVirtual) - h / 2;
  // Every button ships with a second copy of the art with the gradient
  // shifted; that is the hover state. Falls back to the base art if a
  // particular button never got one drawn.
  const hot = mouseX >= x && mouseX <= x + w && mouseY >= y && mouseY <= y + h;
  const im = (hot && IMG['ui.' + key + 'Hover']) || base;
  sctx.imageSmoothingEnabled = false;
  sctx.drawImage(im, x, y, w, h);
  uiButtons.push({ x: x, y: y, w: w, h: h, action: action });
}

/* Menu keys are derived from the gameplay bindings rather than repeated, so
   remapping a button cannot leave the menus answering to a key that no longer
   exists -- which is exactly what happened when attack moved from F to G. */
function menuConfirm() {
  if (tapped('Enter') || tapped('Space')) return true;
  for (const b of BINDS) {
    if (tapped(b.attack) || (b.attack2 && tapped(b.attack2))) return true;
  }
  return false;
}
function menuBack() {
  return tapped('Escape') || tapped('Backspace');
}

/* Shield doubles as "back" on the menus, but deliberately NOT through
   menuBack(): updateBattle uses that to quit a match, and a shield button
   that quits the fight is not a shield button. */
function menuBackOrShield() {
  if (menuBack()) return true;
  for (const b of BINDS) {
    if (tapped(b.shield) || (b.shield2 && tapped(b.shield2))) return true;
  }
  return false;
}

/* A key code as a player would recognise it on screen. */
const KEY_LABELS = {
  Comma: ',', Period: '.', Slash: '/', Semicolon: ';', Quote: "'",
  ShiftLeft: 'SHIFT', ShiftRight: 'SHIFT', Space: 'SPACE', Enter: 'ENTER',
};
function keyName(code) {
  if (KEY_LABELS[code]) return KEY_LABELS[code];
  return code.replace(/^Key/, '').replace(/^Numpad/, 'num');
}

/* =====================================================================
   HELPERS
   ===================================================================== */

const clamp = (v, lo, hi) => (v < lo ? lo : v > hi ? hi : v);
const rand = (a, b) => a + Math.random() * (b - a);

function overlap(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x &&
         a.y < b.y + b.h && a.y + a.h > b.y;
}

/* =====================================================================
   FIGHTER
   ===================================================================== */

const HURT_W = 9;
const HURT_H = 14;

class Fighter {
  constructor(key, slot, cpu, count, scheme) {
    this.key = key;
    this.def = ROSTER[key];
    this.slot = slot;
    this.cpu = cpu;
    // How many are in this match, so spawn and respawn placement can spread
    // to fit rather than assuming an opponent on the far side.
    this.count = count || 2;
    // Which control scheme drives this fighter: an index into BINDS for a
    // keyboard player, 'pad0'..'pad3' for a gamepad, or null for a CPU.
    this.scheme = scheme === undefined ? (cpu ? null : slot) : scheme;
    this.accent = SPRITES[key].accent;

    const sp = spawnFor(slot, this.count);
    this.x = sp.x;
    this.y = sp.y;
    this.prevY = sp.y;
    this.vx = 0;
    this.vy = 0;
    // Face the middle of the stage. For two players on their hand-placed
    // spawns this is exactly the old `slot === 0 ? 1 : -1`; for four it is
    // the only rule that still means anything.
    this.facing = sp.x < VW / 2 ? 1 : -1;
    this.grounded = true;

    this.health = COMBAT.maxHealth;
    this.stocks = COMBAT.stocks;
    this.eliminated = false;

    this.jumpsLeft = PHYS.airJumps;
    this.state = 'idle';        // idle walk air attack special shield roll dodge hitstun ko break
    this.timer = 0;
    this.hitstun = 0;
    this.hitstop = 0;
    this.invuln = COMBAT.respawnInvuln;
    this.landLag = 0;
    this.dropThrough = 0;
    this.hazardCd = 0;
    this.ultMeter = 0;
    this.poisonBy = -1;
    this.combo = 0;
    this.sinceHitFrames = 999;
    this.volleyOf = null;
    // Which fighter that volley belongs to. Two people can pick the same
    // character now, and the move object alone cannot tell them apart.
    this.volleyBy = -1;
    this.volleyHits = 0;
    this.volleySince = 999;
    this.mana = COMBAT.manaMax;
    this.manaDenied = 0;
    this.poison = 0;
    this.poisonDps = 0;

    this.shield = COMBAT.shieldMax;
    this.shieldBroken = 0;

    this.attackFrame = 0;
    this.attackKind = null;     // 'jab' | 'special'
    this.hasHit = false;
    this.specialSpawned = false;

    this.buffTimer = 0;
    this.buffStats = null;
    this.walkAnim = 0;
    // Trev's ult hands him a sword for ten seconds. While swordTimer is
    // running the ult button swings it instead of casting anything.
    this.swordTimer = 0;
    this.swordSwing = false;
    // A song, once started, keeps playing without him standing in it.
    this.rainTimer = 0;
    this.rainSpec = null;
    this.rainStep = 0;

    this.ai = { timer: 0, plan: 'approach', cooldown: 0, jumpCd: 0,
                aggression: rand(0.5, 0.9) };
  }

  get damageMul() {
    return this.buffTimer > 0 && this.buffStats ? this.buffStats.damageMul : 1;
  }
  get speedMul() {
    return this.buffTimer > 0 && this.buffStats ? this.buffStats.speedMul : 1;
  }
  get kbTakenMul() {
    return this.buffTimer > 0 && this.buffStats ? this.buffStats.knockbackTakenMul : 1;
  }
  get busy() {
    return this.state === 'attack' || this.state === 'special' ||
           this.state === 'roll' || this.state === 'dodge' ||
           this.state === 'hitstun' || this.state === 'ko' || this.state === 'break';
  }
  get invulnerable() {
    if (this.invuln > 0) return true;
    if (this.state === 'roll') {
      return this.timer >= COMBAT.rollInvulnFrom && this.timer <= COMBAT.rollInvulnTo;
    }
    if (this.state === 'dodge') {
      return this.timer >= COMBAT.spotDodgeInvulnFrom && this.timer <= COMBAT.spotDodgeInvulnTo;
    }
    return false;
  }

  hurtbox() {
    return { x: this.x - HURT_W / 2, y: this.y - HURT_H, w: HURT_W, h: HURT_H };
  }

  /* ---- the active hitbox this frame, or null ---- */
  hitbox() {
    if (this.state === 'attack') {
      const m = this.def.jab;
      if (this.attackFrame < m.startup) return null;
      if (this.attackFrame >= m.startup + m.active) return null;
      return { box: this.relBox(m), move: m };
    }
    if (this.state === 'special' || this.state === 'ult') {
      const s = this.moveFor(this.state);
      if (!s || s.kind === 'projectile' || s.kind === 'buff' ||
          s.kind === 'equip' || s.kind === 'swingin' || s.kind === 'weight' ||
          s.kind === 'hamdrop' || s.kind === 'pizza' || s.kind === 'barrage' ||
          s.kind === 'rainbow' || s.kind === 'scatter' ||
          s.kind === 'ball' || s.kind === 'knight' || s.kind === 'rain') return null;
      if (this.attackFrame < s.startup) return null;
      if (this.attackFrame >= s.startup + s.active) return null;
      return { box: this.relBox(s), move: s };
    }
    return null;
  }

  relBox(m) {
    // `ox` is the near edge of the hitbox, measured forward from the
    // fighter's center; the box then extends `w` further forward. Mirroring
    // it for a left-facing fighter is one expression, so a move never needs
    // separate left/right definitions. A negative `ox` reaches behind the
    // fighter, which is how the symmetric moves (shockwave, uppercut) are
    // centered on him.
    return {
      x: this.facing > 0 ? this.x + m.ox : this.x - m.ox - m.w,
      y: this.y + m.oy - m.h / 2,
      w: m.w,
      h: m.h,
    };
  }

  /* ---- per-frame update ---- */
  // No opponent argument: it used to be handed `fighters[1 - i]` and passed
  // straight to updateFree(pad), which never declared it. Anything that
  // genuinely needs a target -- the CPU, the ham -- calls nearestFoe().
  update(pad) {
    if (this.hitstop > 0) { this.hitstop--; return; }
    if (this.eliminated) return;

    if (this.invuln > 0) this.invuln--;
    if (this.buffTimer > 0) this.buffTimer--;
    if (this.rainTimer > 0) {
      this.rainTimer--;
      const r = this.rainSpec;
      if (r && this.rainStep % r.every === 0) {
        const n = this.rainStep / r.every;
        // An even sweep dropped at one constant speed lines every note up on
        // a single diagonal, which reads as a conveyor belt rather than as
        // something falling. This scatters them off it -- derived from the
        // note index, so it is the same shower on both machines.
        const j = (n * 37) % 11;
        projectiles.push(new Pellet(this, r, 0, {
          x: (n * r.stride + r.offset + (j % 5) * 3) % VW,
          y: (STAGE.ceilingY || 0) + 2 + (j % 3) * 6,
          vx: 0,
          vy: r.fallSpeed * (0.82 + (j % 7) * 0.06),
          shape: 'note',
        }));
      }
      this.rainStep++;
    }
    if (this.swordTimer > 0) {
      this.swordTimer--;
      // The fire is drawn into the blade now, so this is just the odd ember
      // coming off it rather than the whole effect.
      if (this.swordTimer % 9 === 0) {
        addEffect('spark', this.x + this.facing * rand(2, 10),
                  this.y - rand(12, 30), '#ff7a1a');
      }
    }
    if (this.sinceHitFrames < 999) this.sinceHitFrames++;
    if (this.volleySince < 999) this.volleySince++;

    // Damage over time. Ticks through everything except being dead, so it
    // keeps working while the victim is in hitstun or shielding.
    if (this.poison > 0) {
      this.poison--;
      this.health -= this.poisonDps;
      if (this.health <= 0) { this.knockOut(); return; }
      const by = fighters[this.poisonBy];
      if (by && by !== this) {
        by.ultMeter = Math.min(COMBAT.ultMax,
          by.ultMeter + this.poisonDps * COMBAT.ultPerDamageDealt);
      }
    }
    if (this.dropThrough > 0) this.dropThrough--;
    if (this.landLag > 0) this.landLag--;
    this.timer++;

    if (this.state === 'ko') {
      this.updateKO();
      return;
    }
    if (this.state === 'break') {
      this.vx *= 0.9;
      this.applyGravity();
      this.move();
      if (this.timer >= COMBAT.shieldBreakStun) {
        this.shield = COMBAT.shieldMax;
        this.setState('idle');
      }
      return;
    }
    if (this.state === 'hitstun') {
      this.hitstun--;
      // Bleed off the horizontal shove so a hit is a nudge, not a journey.
      if (this.vx > 0) this.vx = Math.max(0, this.vx - COMBAT.hitstunDrag);
      else if (this.vx < 0) this.vx = Math.min(0, this.vx + COMBAT.hitstunDrag);
      this.applyGravity();
      this.move();
      if (this.hitstun <= 0) this.setState(this.grounded ? 'idle' : 'air');
      this.checkBlastZones();
      return;
    }
    if (this.state === 'roll') { this.updateRoll(); return; }
    if (this.state === 'dodge') { this.updateDodge(); return; }
    if (this.state === 'attack' || this.state === 'special' ||
        this.state === 'ult') {
      this.updateAttack(pad);
      this.checkBlastZones();
      return;
    }

    this.updateFree(pad);
    this.checkBlastZones();
  }

  updateFree(pad) {
    const d = this.def;
    const speed = d.walk * this.speedMul;

    // --- shield / roll / spot dodge ---
    if (pad.shield && this.grounded && this.landLag <= 0) {
      if (pad.left || pad.right) {
        this.facing = pad.left ? -1 : 1;
        this.rollDir = pad.left ? -1 : 1;
        this.setState('roll');
        return;
      }
      if (pad.down) { this.setState('dodge'); return; }

      this.state = 'shield';
      this.vx *= PHYS.groundFriction;
      this.shield -= COMBAT.shieldDrain;
      if (this.shield <= 0) {
        this.shield = 0;
        this.setState('break');
        this.vy = -3.2;
        this.grounded = false;
      }
      this.applyGravity();
      this.move();
      return;
    }
    if (this.state === 'shield') this.setState('idle');
    if (this.mana < COMBAT.manaMax) {
      this.mana = Math.min(COMBAT.manaMax, this.mana + COMBAT.manaRegen);
    }
    if (this.manaDenied > 0) this.manaDenied--;

    if (this.shield < COMBAT.shieldMax) {
      this.shield = Math.min(COMBAT.shieldMax, this.shield + COMBAT.shieldRegen);
    }

    // --- attacks ---
    if (pad.attack && this.landLag <= 0) {
      this.startAttack('attack');
      return;
    }
    if (pad.ult && this.landLag <= 0 && this.def.ult) {
      // Sword already in hand: the same button swings it, and costs nothing.
      if (this.swordTimer > 0 && this.def.ult.swing) {
        this.swordSwing = true;
        this.startAttack('ult', pad);
        return;
      }
      if (this.ultMeter >= COMBAT.ultMax) {
        this.ultMeter = 0;
        this.swordSwing = false;
        this.startAttack('ult', pad);
        return;
      }
    }
    if (pad.special && this.landLag <= 0) {
      if (this.canSpecial(pad)) {
        this.mana -= this.def.specials[this.slotFor(pad)].mana;
        this.startAttack('special', pad);
        return;
      }
      // Out of mana: say so rather than silently eating the input.
      const wanted = this.def.specials[this.slotFor(pad)];
      if (wanted && this.mana < wanted.mana) this.manaDenied = 18;
    }

    // --- horizontal movement ---
    if (pad.left || pad.right) {
      const dir = pad.left ? -1 : 1;
      this.facing = dir;
      if (this.grounded) {
        this.vx = dir * speed;
        this.walkAnim += 0.16;
      } else {
        this.vx += dir * PHYS.airAccel;
        const cap = PHYS.airDriftMax * this.speedMul;
        this.vx = clamp(this.vx, -cap, cap);
      }
    } else if (this.grounded) {
      this.vx *= PHYS.groundFriction;
      if (Math.abs(this.vx) < 0.05) this.vx = 0;
    }

    // --- jumping ---
    if (pad.jump && this.landLag <= 0) {
      if (this.grounded && pad.down) {
        // Drop through the platform you're standing on.
        this.dropThrough = 10;
        this.grounded = false;
        this.y += 1;
      } else if (this.grounded) {
        this.vy = -d.jump;
        this.grounded = false;
        this.jumpsLeft = PHYS.airJumps;
      } else if (this.jumpsLeft > 0) {
        this.vy = -d.doubleJump;
        this.jumpsLeft--;
        addEffect('puff', this.x, this.y, this.accent);
      }
    }

    this.applyGravity(pad.down);
    this.move();

    if (this.grounded) {
      this.state = Math.abs(this.vx) > 0.15 ? 'walk' : 'idle';
    } else {
      this.state = 'air';
    }
  }

  canSpecial(pad) {
    const s = this.def.specials[this.slotFor(pad)];
    if (!s) return false;
    if (this.mana < s.mana) return false;
    if (s.maxAlive) {
      return projectiles.filter((b) => b.owner === this).length < s.maxAlive;
    }
    if (s.kind === 'buff') return this.buffTimer <= 0;
    return true;
  }

  startAttack(kind, pad) {
    if (kind === 'special') this.specialSlot = this.slotFor(pad);
    this.setState(kind);
    this.attackKind = kind;
    this.attackFrame = 0;
    this.hasHit = false;
    this.specialSpawned = false;
    if (this.grounded) this.vx *= 0.4;
  }

  // Which special was pressed. A character without a move in that slot
  // falls back to neutral rather than doing nothing.
  slotFor(pad) {
    const want = pad && pad.spUp ? 'up' : pad && pad.spDown ? 'down' : 'neutral';
    return this.def.specials[want] ? want : 'neutral';
  }

  moveFor(state) {
    return state === 'attack' ? this.def.jab
         : state === 'ult'
           ? (this.swordSwing && this.def.ult.swing ? this.def.ult.swing
                                                    : this.def.ult)
         : this.def.specials[this.specialSlot || 'neutral'];
  }

  updateAttack(pad) {
    const m = this.moveFor(this.state);
    const total = m.startup + m.active + m.recovery;
    this.attackFrame++;

    if (this.state === 'special' || this.state === 'ult') this.runSpecial(m);

    // Roots and dashes control their own horizontal motion.
    const rooted = (this.state === 'special' || this.state === 'ult') &&
      ((m.roots && this.grounded) || m.kind === 'dash' || m.kind === 'uppercut');
    if (!rooted) {
      if (this.grounded) this.vx *= PHYS.groundFriction;
      else if (pad && (pad.left || pad.right)) {
        this.vx += (pad.left ? -1 : 1) * PHYS.airAccel * 0.5;
        this.vx = clamp(this.vx, -PHYS.airDriftMax, PHYS.airDriftMax);
      }
    }

    this.applyGravity();
    this.move();

    if (this.attackFrame >= total) {
      this.setState(this.grounded ? 'idle' : 'air');
      this.landLag = PHYS.landLag;
    }
  }

  runSpecial(s) {
    switch (s.kind) {
      case 'projectile':
        if (this.attackFrame === s.startup && !this.specialSpawned) {
          this.specialSpawned = true;
          projectiles.push(new Bone(this, s));
        }
        break;

      case 'pizza':
        if (this.attackFrame === s.startup && !this.specialSpawned) {
          this.specialSpawned = true;
          // In the air it goes down, which is what PizzaD was drawn for.
          const heading = this.grounded ? (this.facing > 0 ? 'R' : 'L') : 'D';
          projectiles.push(new Pizza(this, s, heading));
        }
        break;

      case 'rainbow':
        if (this.attackFrame === s.startup && !this.specialSpawned) {
          this.specialSpawned = true;
          projectiles.push(new Rainbow(this, s));
        }
        break;

      // A handful of something thrown in a fan.
      case 'scatter':
        if (this.attackFrame === s.startup && !this.specialSpawned) {
          this.specialSpawned = true;
          for (let i = 0; i < s.count; i++) {
            const spread = (i - (s.count - 1) / 2) * s.spread;
            projectiles.push(new Pellet(this, s, spread, null, i));
          }
          // Cereal comes with milk. A square on its own could be anything;
          // a square in a spray of milk is unmistakably breakfast.
          if (s.milk) {
            for (let i = 0; i < 8; i++) {
              const e = addEffect('milk', this.x + this.facing * 7, this.y - 9);
              if (e) {
                e.vx = this.facing * rand(0.8, 2.8);
                e.vy = rand(-1.7, -0.1);
                e.life = 24;
              }
            }
          }
        }
        break;

      case 'ball':
        if (this.attackFrame === s.startup && !this.specialSpawned) {
          this.specialSpawned = true;
          projectiles.push(new Ball(this, s));
        }
        break;

      case 'knight':
        if (this.attackFrame === s.startup && !this.specialSpawned) {
          this.specialSpawned = true;
          projectiles.push(new KnightPiece(this, s));
        }
        break;

      // Notes fall from the ceiling, sweeping across the stage. Deterministic
      // because the simulation has to stay in step online, and a sweep rather
      // than a scattered pattern because a sweep is something you can move
      // around: it threatens every position in turn instead of leaving fixed
      // blind spots where standing still happens to be safe.
      // Start the song. The notes fall on their own timer from here, so the
      // cast is over in half a second and he is free for the rest of it.
      case 'rain':
        if (this.attackFrame === s.startup && !this.specialSpawned) {
          this.specialSpawned = true;
          this.rainTimer = s.duration;
          this.rainSpec = s;
          this.rainStep = 0;
          addEffect('ring', this.x, this.y - 8, s.tints[0]);
        }
        break;

      case 'kiss':
        if (this.attackFrame === s.startup) {
          addEffect('lips', this.x + this.facing * 9, this.y - 11, '#ff5f8f');
        }
        break;

      // A fan of bones at once, rather than one at a time.
      case 'barrage':
        if (this.attackFrame === s.startup && !this.specialSpawned) {
          this.specialSpawned = true;
          for (let i = 0; i < s.count; i++) {
            const shot = new Bone(this, s);
            shot.vy = s.lift - (i - (s.count - 1) / 2) * s.spread;
            projectiles.push(shot);
          }
        }
        break;

      // A committed charge across the ground. Invulnerable through the
      // wind-up so it can be thrown out as a comeback rather than only as a
      // punish.
      case 'rush':
        if (this.attackFrame < s.startup) {
          this.invuln = Math.max(this.invuln, 2);
          if (this.attackFrame % 4 === 0) {
            addEffect('spark', this.x + rand(-10, 10), this.y - rand(2, 18), s.tint);
          }
        }
        if (s.blade && this.attackFrame >= s.startup &&
            this.attackFrame < s.startup + s.active && this.attackFrame % 3 === 0) {
          addEffect('blade', this.x + this.facing * 10, this.y - 12, s.blade);
        }
        if (this.attackFrame === s.startup) {
          addEffect('rush', this.x, this.y - 10, s.tint, this.facing, s);
          this.vx = this.facing * (s.lunge || 0);
        }
        break;

      // Put it up, let it come down, let the floor deal with it.
      case 'weight':
        if (this.attackFrame === s.startup && !this.specialSpawned) {
          this.specialSpawned = true;
          projectiles.push(new Weight(this, s));
        }
        break;

      // He points at the sky. What lands is not his problem.
      case 'hamdrop':
        if (this.attackFrame === s.startup && !this.specialSpawned) {
          this.specialSpawned = true;
          projectiles.push(new HamDrop(this, s));
          addEffect('ring', this.x, this.y - 24, '#f7cd4a');
          for (let i = 0; i < 10; i++) {
            addEffect('spark', this.x + rand(-9, 9), this.y - rand(14, 32), '#f7cd4a');
          }
        }
        break;

      // Somebody swings in out of the trees.
      case 'swingin':
        if (this.attackFrame === s.startup && !this.specialSpawned) {
          this.specialSpawned = true;
          projectiles.push(new Swinger(this, s));
          addEffect('ring', this.x, this.y - 8, s.tint || '#8cea1d');
        }
        break;

      // Hand over the sword. No hitbox of its own -- the ten seconds
      // afterwards are the attack.
      case 'equip':
        if (this.attackFrame === s.startup && !this.specialSpawned) {
          this.specialSpawned = true;
          this.swordTimer = s.duration;
          addEffect('ring', this.x, this.y - 8, s.blade);
          for (let i = 0; i < 16; i++) {
            addEffect('spark', this.x + rand(-7, 7), this.y - rand(2, 20), s.blade);
          }
        }
        break;

      // One swing of it, which throws a laser as well as cutting.
      case 'laser': {
        const k = this.attackFrame - s.startup;
        // An afterimage per frame of the arc.
        if (k >= 0 && k < SWORD_SWING.length) {
          const ghost = addEffect('blademark', swordHandX(this), swordHandY(this),
                                  s.blade, this.facing, SWORD_SWING[k]);
          if (ghost) ghost.life = 9;
        }
        if (this.attackFrame === s.startup && !this.specialSpawned) {
          this.specialSpawned = true;
          for (let i = 0; i < 8; i++) {
            addEffect('spark', this.x + this.facing * rand(6, 22),
                      this.y - rand(2, 24), s.blade);
          }
        }
        // The bolt leaves at the bottom of the arc, off the tip, not on the
        // first frame of the wind-up.
        if (k === 2 && s.beam) projectiles.push(new Laser(this, s.beam));
        break;
      }

      case 'buff':
        if (this.attackFrame === s.startup && !this.specialSpawned) {
          this.specialSpawned = true;
          this.buffTimer = s.duration;
          // Read from the move that actually granted it, whichever slot
          // that move happens to occupy.
          this.buffStats = {
            damageMul: s.damageMul || 1,
            speedMul: s.speedMul || 1,
            knockbackTakenMul: s.knockbackTakenMul || 1,
          };
          for (let i = 0; i < 10; i++) addEffect('spark', this.x, this.y - 7, this.accent);
          // The shirt has to go somewhere.
          if (s.shirt) projectiles.push(new Pellet(this, s.shirt, 0));
        }
        break;

      case 'dash':
        if (this.attackFrame === s.startup) this.dashStopped = false;
        if (this.attackFrame >= s.startup &&
            this.attackFrame < s.startup + s.active) {
          // A dash that starts on the ground stops at the ledge instead of
          // launching its owner into the blast zone -- "closes distance
          // instantly" shouldn't cost a stock. The cancel latches, because
          // the moment she clears the edge `grounded` goes false and an
          // unlatched check would hand the momentum straight back.
          // A dash begun in mid-air keeps its speed and works as a recovery.
          if (this.grounded && !this.groundAhead(18)) this.dashStopped = true;
          if (this.dashStopped) {
            this.vx *= 0.5;
          } else {
            this.vx = this.facing * s.speed;
            this.vy = Math.min(this.vy, 0.4);
          }
          if (this.attackFrame % 3 === 0) {
            addEffect('trail', this.x, this.y - 7, this.accent);
          }
        }
        break;

      // A melee swing had no handler at all, which is why it drew nothing.
      case 'swing':
        if (this.attackFrame === s.startup) {
          addEffect('swipe', this.x, this.y - 9,
                    s.tint || '#ffffff', this.facing);
          // A move named after an object should show the object.
          if (s.sticks) {
            for (let i = 0; i < 2; i++) {
              const e = addEffect('stick', this.x + this.facing * (6 + i * 3),
                                  this.y - 12 + i * 4, s.sticks, this.facing);
              if (e) {
                e.vx = this.facing * (1.1 + i * 0.5);
                e.vy = -1.4 + i * 0.5;
                e.life = 18;
              }
            }
          }
        }
        break;

      case 'uppercut':
        if (s.blade && this.attackFrame >= s.startup &&
            this.attackFrame < s.startup + s.active && this.attackFrame % 2 === 0) {
          addEffect('blade', this.x + this.facing * 4, this.y - 14, s.blade);
        }
        // Something pressed overhead, drawn above him the whole way up.
        if (s.overhead && this.attackFrame >= s.startup &&
            this.attackFrame < s.startup + s.active) {
          addEffect('bar', this.x, this.y - 24, s.overhead);
        }
        // A geyser throws its own contents about. Droplets come off the
        // column the whole way up, not just at the start, so the move reads
        // as a spray rather than a puff.
        if (s.spray && this.attackFrame >= s.startup &&
            this.attackFrame < s.startup + s.active) {
          for (let i = 0; i < 2; i++) {
            addEffect('milk', this.x + rand(-4, 4), this.y - rand(6, 20));
          }
        }
        if (this.attackFrame === s.startup) {
          if (s.spray) {
            // A bigger burst off the ground as it goes off.
            for (let i = 0; i < 7; i++) {
              addEffect('milk', this.x + rand(-6, 6), this.y - rand(2, 10));
            }
          }
          this.vy = s.rise;
          this.vx = this.facing * s.drift;
          this.grounded = false;
        }
        break;

      case 'shockwave':
        if (this.attackFrame === s.startup) {
          addEffect('ring', this.x, this.y, this.accent);
          this.vy = Math.max(this.vy, 0);
        }
        break;

      case 'beam':
        if (this.attackFrame === s.startup) {
          addEffect('beam', this.x, this.y + s.oy, this.accent, this.facing, s);
        }
        break;
    }
  }

  updateRoll() {
    const t = COMBAT.rollFrames;
    // Ease out so the roll covers ground early and settles.
    this.vx = this.rollDir * (COMBAT.rollDistance / t) * 2 * (1 - this.timer / t);
    this.applyGravity();
    this.move();
    if (this.timer >= t) this.setState('idle');
  }

  updateDodge() {
    this.vx *= 0.8;
    this.applyGravity();
    this.move();
    if (this.timer >= COMBAT.spotDodgeFrames) this.setState('idle');
  }

  updateKO() {
    this.vy += PHYS.gravity * 0.5;
    this.x += this.vx;
    this.y += this.vy;
    if (this.timer >= 40) this.respawn();
  }

  groundAhead(lookahead) {
    const probe = this.x + this.facing * (lookahead || 9);
    return STAGE.platforms.some(
      (p) => probe >= p.x && probe <= p.x + p.w && Math.abs(this.y - p.y) < 2
    );
  }

  applyGravity(fastFall) {
    const g = PHYS.gravity;
    this.vy += g;
    let cap = PHYS.maxFall;
    if (fastFall && this.vy > 0) cap *= PHYS.fastFallMul;
    if (this.vy > cap) this.vy = cap;
  }

  move() {
    this.prevY = this.y;
    this.x += this.vx;
    this.y += this.vy;
    this.collidePlatforms();
    this.collideCeiling();
  }

  collideCeiling() {
    // Enclosed stages have a solid lid, so there are no upward KOs on them.
    if (STAGE.ceilingY === null) return;
    const head = this.y - HURT_H;
    if (head < STAGE.ceilingY) {
      this.y = STAGE.ceilingY + HURT_H;
      if (this.vy < 0) this.vy = 0;
    }
  }

  // The lava floor isn't ground -- it burns and throws you upward, which at
  // high damage is what actually kills you on that stage. Bounded to the
  // visible width so a hard launch off the side still falls out of bounds.
  checkHazard() {
    const hz = STAGE.hazard;
    if (!hz) return;
    if (this.hazardCd > 0) { this.hazardCd--; return; }
    if (this.y < hz.y || this.x < 0 || this.x > VW) return;
    if (this.invuln > 0) return;

    this.health -= hz.damage;
    if (this.health <= 0) { this.knockOut(); return; }
    this.vy = hz.launch;
    this.vx *= 0.4;
    this.grounded = false;
    this.hazardCd = hz.cooldown;
    this.setState('hitstun');
    this.hitstun = 18;
    this.hitstop = COMBAT.hitstopLight;
    for (let i = 0; i < 7; i++) addEffect('spark', this.x, hz.y, '#ff8a2a');
    addEffect('hit', this.x, hz.y - 4, '#ffb347');
  }

  collidePlatforms() {
    if (this.vy < 0 || this.dropThrough > 0) {
      if (this.grounded && this.dropThrough > 0) this.grounded = false;
      if (this.vy < 0) this.grounded = false;
      return;
    }
    const wasGrounded = this.grounded;
    this.grounded = false;
    for (const p of STAGE.platforms) {
      if (this.x < p.x - 3 || this.x > p.x + p.w + 3) continue;
      // One-way: only catch a fighter crossing the surface downward.
      if (this.prevY <= p.y + 0.6 && this.y >= p.y) {
        this.y = p.y;
        this.vy = 0;
        this.grounded = true;
        this.jumpsLeft = PHYS.airJumps;
        if (!wasGrounded) {
          this.landLag = PHYS.landLag;
          addEffect('dust', this.x, this.y, '#ffffff');
        }
        return;
      }
    }
  }

  checkBlastZones() {
    if (this.state === 'ko' || this.eliminated) return;
    this.checkHazard();
    const bz = STAGE.blast;
    if (this.x < bz.left || this.x > bz.right ||
        this.y < bz.top || this.y > bz.bottom) {
      this.koed();
    }
  }

  // Health ran out.
  knockOut() {
    if (this.state === 'ko' || this.eliminated) return;
    this.health = 0;
    this.vy = -3.2;
    this.grounded = false;
    for (let i = 0; i < 10; i++) addEffect('spark', this.x, this.y - 8, this.accent);
    this.koed();
  }

  koed() {
    this.stocks--;
    this.setState('ko');
    this.timer = 0;
    freezeFrames = 12;
    announce(this.def.name + ' KO!', this.accent);
    if (this.stocks <= 0) {
      this.eliminated = true;
      this.state = 'gone';
    }
  }

  respawn() {
    // Fan out around the respawn point so four people do not all drop onto
    // the same pixel. Two players keep the +/-22 they always had.
    const step = this.count === 2 ? 44 : 30;
    this.x = STAGE.respawn.x + (this.slot - (this.count - 1) / 2) * step;
    this.y = STAGE.respawn.y;
    this.prevY = this.y;
    this.vx = 0;
    this.vy = 0;
    this.health = COMBAT.maxHealth;
    this.combo = 0;
    this.volleyOf = null;
    this.volleyBy = -1;
    this.shield = COMBAT.shieldMax;
    this.buffTimer = 0;
    this.buffStats = null;
    this.poison = 0;
    this.mana = COMBAT.manaMax;
    this.hitstun = 0;
    this.invuln = COMBAT.respawnInvuln;
    this.hazardCd = 0;
    this.grounded = false;
    this.jumpsLeft = PHYS.airJumps;
    this.setState('air');
  }

  setState(s) {
    this.state = s;
    this.timer = 0;
  }

  /* ---- which frame to draw ---- */
  sprite() {
    const entry = SPRITES[this.key];
    let set = 'base';
    // There is a real attack animation for him -- use it when he swings.
    if (entry.attack && (this.state === 'attack' || this.state === 'special' ||
                         this.state === 'ult')) {
      set = 'attack';
    }
    // Reese's shirtless set is his buff state, exactly as drawn.
    if (entry.shirtless && this.buffTimer > 0) set = 'shirtless';

    const d = this.facing > 0 ? 'R' : 'L';
    let frame;
    if (this.state === 'ko' || this.state === 'break') {
      frame = 'jump' + d;
    } else if (!this.grounded) {
      frame = 'jump' + d;
    } else if (this.state === 'walk' || this.state === 'roll') {
      frame = 'walk' + d + ((Math.floor(this.walkAnim) % 2) + 1);
    } else {
      frame = 'stand' + d;
    }
    return IMG[this.key + '.' + set + '.' + frame];
  }
}

/* =====================================================================
   PIXEL ART

   Sprites for things nobody drew in 2016, written as strings so the shape is
   visible in the source and can be edited without a paint program. Each one
   is rasterised once into its own little canvas and blitted after that --
   a 6x6 sprite is 36 fillRect calls, and there can be a dozen on screen.

   Purely presentational: none of this is reachable from the simulation, so
   it cannot affect a rollback or desync anything.
   ===================================================================== */

const artCache = new Map();

/** rows: array of equal-length strings. palette: char -> css colour. */
function pixelArt(key, rows, palette, flip) {
  const hit = artCache.get(key);
  if (hit) return hit;

  const w = rows[0].length, h = rows.length;
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  const g = c.getContext('2d');
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const col = palette[rows[y][flip ? w - 1 - x : x]];
      if (!col) continue;
      g.fillStyle = col;
      g.fillRect(x, y, 1, 1);
    }
  }
  artCache.set(key, c);
  return c;
}

/** Blit a sprite centred on a world position, snapped to whole pixels. */
function drawArt(g, art, x, y) {
  g.drawImage(art, Math.round(x) - (art.width >> 1),
                   Math.round(y) - (art.height >> 1));
}

/** The same, blown up by a whole-number factor. Nearest-neighbour is already
    on for this context, so a 23x19 sprite drawn at 3x stays a crisp 69x57
    instead of turning to mush -- which is why the ham is stored small. */
function drawArtBig(g, art, x, y, s) {
  const w = art.width * s, h = art.height * s;
  g.drawImage(art, Math.round(x) - (w >> 1), Math.round(y) - (h >> 1), w, h);
}

